mapper.select:
SELECT tdm05_company_id
  FROM tdm05_cncl
 WHERE tdm05_cncl_id = #{cnclId}

mapper.update:
UPDATE tdm05_cncl
   SET tdm05_cncl_nm        = #{row.cnclName}
     , tdm05_open_cycle_cd  = #{row.openCycleCode}
     , tdm05_main_decision  = #{row.mainDecision}
     , tdm05_start_date     = #{row.startDate}
     , tdm05_end_date       = #{row.endDate}
     , tdm05_upd_nm         = #{updName}
     , tdm05_upd_date       = f_sysdate()
 WHERE tdm05_cncl_id = #{row.cnclId}

mapper.delete:
DELETE FROM tdm05_cncl
 WHERE tdm05_cncl_id IN
#{id}

mapper.select:
SELECT tdm20_company_id
  FROM tdm20_role
 WHERE tdm20_role_id = #{roleId}

mapper.update:
