   SET tdm22_member_type = #{row.memberType}
     , tdm22_start_date  = #{row.startDate}
     , tdm22_end_date    = #{row.endDate}
 WHERE tdm22_role_relate_cncl_id = #{row.roleRelateCnclId}

mapper.delete:
DELETE FROM tdm22_role_relate_cncl
 WHERE tdm22_role_relate_cncl_id IN
#{id}
